import{_ as a,o as r,c as t,a6 as i}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"TikTools 4.2.1-rc.1 候補の記録","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.1 候補の記録","docId":"releases.4.2.1-rc.1","translationKey":"releases.4.2.1-rc.1","locale":"ja","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f2b9e975511584a1a6156af8326d7603d73be54f10c97d7e46ed385def4755f6","translationRevision":"acbebed85ef2e04e1871076b353e944b075c0b08f27b77235e5543ef0967e58f","order":10},"headers":[],"relativePath":"ja/releases/4.2.1-rc.1.md","filePath":"ja/releases/4.2.1-rc.1.md","lastUpdated":1794611623000}'),o={name:"ja/releases/4.2.1-rc.1.md"};function l(s,e,c,n,d,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="tiktools-421-rc1" tabindex="-1">TikTools 4.2.1-rc.1 <a class="header-anchor" href="#tiktools-421-rc1" aria-label="Permalink to &quot;TikTools 4.2.1-rc.1 {#tiktools-421-rc1}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">目的・状況・前提条件 <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;目的・状況・前提条件 {#goal-status-and-prerequisites}&quot;">​</a></h2><p>この過去の候補記録を使い、RC1 で調査した Cloud 復旧、チーム、Linux AppImage の問題を再現します。対象はアプリ基準 <code>338495a9</code> と別のバックエンド基準 <code>6a69c99</code> です。現在 RC1 を取得できることは示しません。インストーラーを選ぶ前に<a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">公開アセット</a> を確認します。</p><p>記録された候補は Actions 無効中にローカルで作った Linux AppImage、DEB、可搬型パッケージを使いました。新規 Windows インストーラーは含みません。移行テストにはバックアップと影響プロファイルの分離コピーを用意します。共同操作と Cloud セクションの復旧は実験段階です。</p><h2 id="changes-in-this-candidate" tabindex="-1">この候補の変更 <a class="header-anchor" href="#changes-in-this-candidate" aria-label="Permalink to &quot;この候補の変更 {#changes-in-this-candidate}&quot;">​</a></h2><ul><li>設定はアカウント・セッションと診断を保持し、プラグインがカタログ、検索、変更、インストールを担当します。テンプレートとプロファイルは自動化にあります。</li><li>共有変更パネルは比較失敗と正常な空結果を区別します。プラグインの送信は自身の選択・設定だけを送り、他の待機列と取得キャッシュを保ちます。</li><li>移行は暗黙の同梱プラグインディレクトリがなくても許容し、明示パスは厳密に扱い、不足パッケージ ID を示して確認付き修復を行います。保留編集と競合を保持します。</li><li>チームはこの PC のホスト登録と別 PC のホスト選択を区別します。ニックネーム招待は選択宛先に結び付き、所有ホストの承認も必要です。</li><li>任意の操作ガイドは設定状態に従います。Linux パッケージは以後のメディア確認用に WebKit ヘルパー、GStreamer プラグイン、scanner を同梱します。</li></ul><h2 id="reproduce-and-inspect-the-expected-result" tabindex="-1">再現して期待結果を調べる <a class="header-anchor" href="#reproduce-and-inspect-the-expected-result" aria-label="Permalink to &quot;再現して期待結果を調べる {#reproduce-and-inspect-the-expected-result}&quot;">​</a></h2><ol><li>表示バージョンと OS を記録します。プラグイン → 変更を開き、読み込み失敗なら正確なエラーと要求 ID を保持します。</li><li>コピーしたプロファイルで移行をプレビューし、修復前に不足 ID を確認します。修復後も再プレビューし、保留編集と競合が残ることを確認します。</li><li>チームで現在の PC を登録してから「提供を開始」を試します。別 PC のホストを選んでも、この PC の起動権限は得られないはずです。</li><li>AppImage 起動と音声・映像を別々に確認します。画面まで到達してもメディア再生成功の証拠にはなりません。</li></ol><p>ニックネーム検索と宛先固定招待にはバックエンド <code>6a69c99</code> と移行 <code>20261113000001_remote_invitation_recipients.sql</code> が必要です。候補のインストールではバックエンドは配置されません。</p><h2 id="recovery-and-evidence-limits" tabindex="-1">復旧と証拠の制限 <a class="header-anchor" href="#recovery-and-evidence-limits" aria-label="Permalink to &quot;復旧と証拠の制限 {#recovery-and-evidence-limits}&quot;">​</a></h2><p>比較失敗ではネイティブの理由を残し、対応パネルから再試行します。保留状態を消したり、互換性検査から移行成功を推測したりしません。<a href="./../user/preferences/troubleshooting.html">トラブルシューティング</a> に従い、版、操作、秘密除去済み診断を集めます。</p><p>原記録は基準時点のフロントエンド、同期エンジン、宛先分離、2ホストのネイティブ・リレー検査を報告します。日付のある検査で、現在の本番検証ではありません。過去の SQLite ロック保持者は特定されていません。RC1 では変数とオーバーレイの Cloud アダプターは未完了で、自動化はローカル基準と比較していました。後の範囲は<a href="./4.2.1-rc.3.html">後続候補</a> と<a href="./../user/cloud/changes.html">現在の変更ガイド</a> を読みます。</p><p><a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.1.md" target="_blank" rel="noreferrer">元のリリース記録</a> は日付付き証拠として保持されています。<a href="./">リリース一覧に戻る</a>。</p>',13)])])}const f=a(o,[["render",l]]);export{u as __pageData,f as default};
